def get_knowledge_context(self, query: str, limit: int = 5) -> str:
    """为 AI prompt 生成知识上下文（检索 top-N 资产摘要）。"""
    assets = self.search_assets(query, limit=limit)
    if not assets:
        return ""
    lines = ["【语义记忆检索结果】"]
    for a in assets:
        title = a.get("title", "未知")
        summary = (a.get("summary") or "")[:200]
        tags = a.get("tags", "")
        lines.append(f"- [{a.get('sub_library','')}] {title}: {summary} (tags: {tags})")
    return "\n".join(lines)

def _store(self, record: MemoryRecord) -> bool:
    self._in_memory[record.key] = record
    return True

def _query(self, filters: Dict[str, Any], limit: int) -> List[MemoryRecord]:
    results = []
    for rec in self._in_memory.values():
        match = True
        for fk, fv in filters.items():
            if fk == "keyword":
                text = json.dumps(rec.value, ensure_ascii=False).lower()
                if str(fv).lower() not in text:
                    match = False
                    break
            elif fk == "source":
                if rec.source != fv:
                    match = False
                    break
            elif fk in rec.metadata:
                if rec.metadata[fk] != fv:
                    match = False
                    break
        if match:
            results.append(rec)
    results.sort(key=lambda r: r.timestamp, reverse=True)
    return results[:limit]
